    'No marketing cookies are used on this site.' => 'Šajā vietnē netiek izmantotas mārketinga sīkdatnes.',
    'No new cookies found.' => 'Jaunas sīkdatnes netika atrastas.',
    'No preference cookies are used on this site.' => 'Šajā vietnē netiek izmantotas preferenču sīkdatnes.',
